def compute(vars):
    size_sq_ft = vars["v1"]
    center_count = vars["v2"]

    if center_count == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "square feet"}}}

    average_size_sq_ft = size_sq_ft / center_count
    return {
        "value": average_size_sq_ft,
        "trace": {
            "total_size_sq_ft": size_sq_ft,
            "center_count": center_count,
            "output_meta": {"currency": None, "scale": None, "unit": "square feet"},
        },
    }
